import"./chunks/assets.Cp_lF0-_.js";import{E as e,at as t,it as n,vt as r}from"./chunks/framework.DwjJr7zi.js";var i=JSON.parse(`{"title":"iOS 代理 App 怎么选","description":"","frontmatter":{"title":"iOS 代理 App 怎么选"},"headers":[],"relativePath":"blog/posts/751.md","filePath":"blog/posts/751.md","lastUpdated":1783382106000}`),a={name:`blog/posts/751.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="ios-代理-app-怎么选" tabindex="-1">iOS 代理 App 怎么选 <a class="header-anchor" href="#ios-代理-app-怎么选" aria-label="Permalink to “iOS 代理 App 怎么选”">​</a></h1><img class="telegram-media" src="/telegram/AQADXrUxG08tMFZ8.jpg" alt="Telegram 图片" loading="lazy" decoding="async"><div class="telegram-content">💡 iOS 代理 App 怎么选<br> <br>👉🏻 先看 🍟 薯薯总结的 <a href="https://trello.com/b/5qmVzMIg/ios%E4%B8%BB%E6%B5%81vpn%E5%8A%9F%E8%83%BD%E5%B7%AE%E5%BC%82">iOS 主流 VPN 功能差异</a> 明确大的优缺点(<s>记得喊薯薯更新</s>)<br><br>1. 需要 MitM SNI 的<br><br>如果不支持, 可能用不了或要很麻烦才能用上微博/网易云音乐/美团等脚本<br><br>短期内无法实现/优先级低/没有计划/明确不会支持: LanceX<br><br>2. 需要协议和端口分流<br><br>如果不支持, 就不能按 UDP/TCP 和目标的端口分流<br><br>👍 推荐: Stash, Surge<br><br>勉强可用: Loon (逻辑规则里不支持订阅规则)<br><br>🙅🏻‍QX<br><br>3. 需要百度代理(即 &quot;百度直连&quot;)<br><br>协议支持且至少应该支持按协议分流(目前百度又不限端口了)<br><br>👍 推荐: Stash<br><br>其他: Egern(2025-02-19 开始支持), Loon(逻辑规则里不支持订阅规则), Shadowrocket(上次看的时候, 用 AND 语法实现按协议&amp;规则集分流有问题, 后面没跟进), LanceX(支持逻辑规则, 但是未测试), Pharos Pro( 1.8.6(33) TestFlight 版开始支持 <a href="https://t.me/Pharos_x_Announcements/167">查看详情.</a> 脚本功能还在开发中)<br><br>3.1 补充: 所谓的 &quot;钉钉直连&quot;/&quot;三爱直连&quot;<br><br>某些极端 ML 佬懂的<br><br>Loon, Shadowrocket, Pharos Pro 能实现, 缺陷见 3 所述<br><br>4. 需要 MitM over HTTP/2 的<br><br>如果不支持, 你用不了类似 🍟 薯薯的 <a href="https://github.com/BiliUniverse/Universe/wiki/%F0%9F%8C%90-Global">📺 BiliBili: 🌐 Global - 哔哩哔哩：全球模式（中国站自动线路及全区搜索）的脚本</a><br><br>目前不支持的: Shadowrocket, QX<br><br>5. 需要 HTTP API 的<br><br>若需要用到 <a href="https://manual.nssurge.com/others/http-api.html">这里</a> 的功能 那么你只能选择 Surge<br>Stash 有部分接口, 可以实现部分功能 具体请看文档(Clash RESTful API)<br>Loon 有 <code>setSelectPolicy</code> <code>getSubPolicys</code> <code>getSubPolicies</code> <code>getPolicy</code> <code>getSelectedPolicy</code> 之类的接口<br>QX 有 <code>$configuration.sendMessage</code> ) <br><br>例如我的 <a href="/blog/posts/1117">网络信息</a> 脚本 就依赖部分接口<br><br>6. 脚本<br><br><a href="https://github.com/Script-Hub-Org/Script-Hub">Script Hub</a> 能转换部分脚本(包括加密脚本), 但是可能需要投入更多的精力, 具备一定的动手能力<br><br>7. <s>需要 </s><code>WKWebView</code><s>, Web API</s> 的<br><br><blockquote class="telegram-blockquote"><pre class="telegram-blockquote-content"><s>主流 iOS 代理 App 已全面换用或新增 WKWebView 做为 JavaScript 脚本运行环境
并增加大量 Web API</s></pre></blockquote><s><br><br>Shadowrocket 仅有 JavaScriptCore</s><br><br>Shadowrocket 2.2.78 (3010) 开始加了 webview script engine<br><br>8. 更多的需求<br><br>Surge 支持 <a href="https://manual.nssurge.com/others/http-api.html">HTTP API 获取数据/进行各种修改和控制</a>, <a href="https://manual.nssurge.com/rule/misc-rule.html">更多的分流规则</a>, <a href="https://manual.nssurge.com/scripting/event.html">在发送通知时执行脚本</a> , <a href="https://manual.nssurge.com/scripting/dns.html">DNS 脚本</a>, <a href="https://kb.nssurge.com/surge-knowledge-base/zh/guidelines/smart-group">Smart 策略组</a><br><br><img class="telegram-custom-emoji" src="/telegram/AgAEDgACMozQVw.webp" alt="🤭" loading="lazy" decoding="async"> <a href="/blog/222/">模块脚本合集</a> <img class="telegram-custom-emoji" src="/telegram/AgADRw4AApYl0Vc.webp" alt="🧐" loading="lazy" decoding="async"> <a href="/blog/">频道资源合集</a> <img class="telegram-custom-emoji" src="/telegram/AgADmw4AArTV0Fc.webp" alt="😄" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha/957">恰饭推荐</a> <img class="telegram-custom-emoji" src="/telegram/AgAD3A4AAjTykVM.webp" alt="💬" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha_group">群组</a><br><br><img class="telegram-custom-emoji" src="/telegram/AgAD_A0AAh_-0Fc.webp" alt="🥰" loading="lazy" decoding="async"> #代理 #iOS #App</div><p class="telegram-source"><a href="https://t.me/zhetengsha/751">查看 Telegram 原文</a></p>`,4)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};